class Node:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None


class BinarySearchTree:
    def __init__(self):
        self.root = None

    def insert(self, value):
        if self.root is None:
            self.root = Node(value)
        else:
            self._insert_recursive(self.root, value)

    def _insert_recursive(self, node, value):
        if value < node.value:
            if node.left is None:
                node.left = Node(value)
            else:
                self._insert_recursive(node.left, value)
        elif value > node.value:
            if node.right is None:
                node.right = Node(value)
            else:
                self._insert_recursive(node.right, value)

    def search(self, value):
        return self._search_recursive(self.root, value)

    def _search_recursive(self, node, value):
        if node is None:
            return False
        if value == node.value:
            return True
        elif value < node.value:
            return self._search_recursive(node.left, value)
        else:
            return self._search_recursive(node.right, value)

    def in_order_traversal(self):
        result = []
        self._in_order_recursive(self.root, result)
        return result

    def _in_order_recursive(self, node, result):
        if node is not None:
            self._in_order_recursive(node.left, result)
            result.append(node.value)
            self._in_order_recursive(node.right, result)


def test_insert_and_search():
    bst = BinarySearchTree()
    bst.insert(5)
    bst.insert(3)
    bst.insert(7)
    bst.insert(1)
    bst.insert(4)

    assert bst.search(5) is True
    assert bst.search(3) is True
    assert bst.search(7) is True
    assert bst.search(1) is True
    assert bst.search(4) is True
    assert bst.search(10) is False
    assert bst.search(0) is False


def test_duplicate_insert():
    bst = BinarySearchTree()
    bst.insert(5)
    bst.insert(5)
    assert bst.in_order_traversal() == [5]


def test_in_order_traversal():
    bst = BinarySearchTree()
    for v in [5, 3, 7, 1, 4, 6, 8]:
        bst.insert(v)
    assert bst.in_order_traversal() == [1, 3, 4, 5, 6, 7, 8]


def test_empty_tree():
    bst = BinarySearchTree()
    assert bst.in_order_traversal() == []
    assert bst.search(1) is False


def test_single_node():
    bst = BinarySearchTree()
    bst.insert(42)
    assert bst.search(42) is True
    assert bst.search(0) is False
    assert bst.in_order_traversal() == [42]


if __name__ == "__main__":
    test_insert_and_search()
    test_duplicate_insert()
    test_in_order_traversal()
    test_empty_tree()
    test_single_node()
    print("All tests passed.")
